-- V90.cz: Manufacturing Scheduling + Capacity Planning
CREATE TABLE IF NOT EXISTS manufacturing_work_center (work_center_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, code TEXT NOT NULL, name TEXT NOT NULL, capacity_per_shift NUMERIC NOT NULL DEFAULT 0, shifts_per_day NUMERIC NOT NULL DEFAULT 1, efficiency_pct NUMERIC NOT NULL DEFAULT 100, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(organization_id,entity_id,code));
CREATE TABLE IF NOT EXISTS manufacturing_shift_calendar (calendar_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, work_date DATE NOT NULL, shift_code TEXT NOT NULL, available_hours NUMERIC NOT NULL DEFAULT 0, available BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(organization_id,entity_id,work_date,shift_code));
CREATE TABLE IF NOT EXISTS manufacturing_schedule (schedule_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, production_order_id TEXT NOT NULL, product_id TEXT NOT NULL, work_center_id TEXT NOT NULL, schedule_date DATE NOT NULL, shift_code TEXT NOT NULL, planned_qty NUMERIC NOT NULL DEFAULT 0, required_hours NUMERIC NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'PLANNED', approved_by TEXT, approved_at TIMESTAMP, created_by TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS manufacturing_schedule_exception (exception_id TEXT PRIMARY KEY, schedule_id TEXT NOT NULL, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, exception_type TEXT NOT NULL, message TEXT NOT NULL, severity TEXT NOT NULL DEFAULT 'WARNING', status TEXT NOT NULL DEFAULT 'OPEN', resolved_by TEXT, resolved_at TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_mfg_sched_scope ON manufacturing_schedule(organization_id,entity_id,schedule_date,work_center_id,status);
